from pathlib import Path
import re

p = Path('index.html')
s = p.read_text()

start = s.find("    const videoObserver=new IntersectionObserver")
end_marker = "}).observe(loader);"
end = s.find(end_marker, start)
if start < 0 or end < 0:
    raise SystemExit('main feed block not found')
end += len(end_marker)

replacement = r'''    function ensureVideoSrc(v){if(!v.getAttribute('src')&&v.dataset.src){v.src=v.dataset.src;v.load()}}
    const lazyVideoObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){ensureVideoSrc(entry.target);lazyVideoObserver.unobserve(entry.target)}}),{rootMargin:'500px 0px'});
    const videoObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{const v=entry.target;if(entry.isIntersecting&&entry.intersectionRatio>=.28){ensureVideoSrc(v);document.querySelectorAll('video.feed-media').forEach(o=>{if(o!==v)o.pause()});const attempt=v.play();if(attempt&&attempt.catch)attempt.catch(()=>{})}else v.pause()}),{threshold:[0,.15,.28,.5]});
    function buildMedia(item){const wrap=document.createElement('article');wrap.className='feed-item';const topBrand=document.createElement('div');topBrand.className='feed-brand';topBrand.textContent='Bluia Sisters';wrap.appendChild(topBrand);if(item.type==='photo'){const img=document.createElement('img');img.className='feed-media photo';img.src=item.src;img.alt='Bluia Sisters photo update';img.loading='lazy';img.decoding='async';wrap.appendChild(img)}else{const video=document.createElement('video');video.className=`feed-media ${item.type}`;video.dataset.src=item.src;video.playsInline=true;video.muted=true;video.defaultMuted=true;video.autoplay=true;video.loop=true;video.preload='none';video.setAttribute('muted','');video.setAttribute('playsinline','');video.setAttribute('webkit-playsinline','');wrap.appendChild(video);const dots=document.createElement('div');dots.className='video-loader show';dots.innerHTML='<span></span><span></span><span></span>';wrap.appendChild(dots);['loadstart','waiting','stalled'].forEach(e=>video.addEventListener(e,()=>dots.classList.add('show')));['canplay','playing'].forEach(e=>video.addEventListener(e,()=>dots.classList.remove('show')));video.addEventListener('error',()=>dots.classList.remove('show'));const controls=document.createElement('div');controls.className='video-controls';const mute=document.createElement('button');mute.className='mini-control';mute.type='button';mute.setAttribute('aria-label','Unmute');mute.innerHTML=iconMute;const full=document.createElement('button');full.className='mini-control';full.type='button';full.setAttribute('aria-label','Full screen');full.innerHTML=iconFull;mute.addEventListener('click',()=>{ensureVideoSrc(video);video.muted=!video.muted;mute.innerHTML=video.muted?iconMute:iconSound;if(video.paused)video.play().catch(()=>{});wakeControls(wrap)});full.addEventListener('click',async()=>{ensureVideoSrc(video);wakeControls(wrap);try{if(document.fullscreenElement)await document.exitFullscreen();else if(wrap.requestFullscreen)await wrap.requestFullscreen();else if(video.webkitEnterFullscreen)video.webkitEnterFullscreen()}catch(e){}});controls.append(mute,full);wrap.appendChild(controls);wrap.addEventListener('pointerdown',()=>wakeControls(wrap));video.addEventListener('click',()=>{ensureVideoSrc(video);if(video.paused)video.play().catch(()=>{})});lazyVideoObserver.observe(video);videoObserver.observe(video)}return wrap}
    let feedObserver=null;
    function appendBatch(count=4){if(loading||cursor>=queue.length)return;loading=true;const frag=document.createDocumentFragment();for(let n=0;n<count&&cursor<queue.length;n++){const item=queue[cursor++];frag.appendChild(buildMedia(item))}feed.appendChild(frag);loading=false;if(cursor>=queue.length&&feedObserver)feedObserver.unobserve(loader)}function finishStartup(){if(!startup||startup.classList.contains('done'))return;startup.classList.add('done');setTimeout(()=>startup.remove(),320)}appendBatch(4);const firstMedia=feed.querySelector('.feed-media');if(firstMedia){if(firstMedia.tagName==='IMG'){if(firstMedia.complete)requestAnimationFrame(finishStartup);else{firstMedia.addEventListener('load',finishStartup,{once:true});firstMedia.addEventListener('error',finishStartup,{once:true})}}else{ensureVideoSrc(firstMedia);firstMedia.addEventListener('canplay',finishStartup,{once:true});firstMedia.addEventListener('error',finishStartup,{once:true})}}setTimeout(finishStartup,2600);feedObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting))appendBatch(4)},{rootMargin:'250px 0px'});if(cursor<queue.length)feedObserver.observe(loader);'''

s = s[:start] + replacement + s[end:]
s = s.replace('class="mag-photo" src=', 'class="mag-photo" loading="lazy" decoding="async" src=')
p.write_text(s)
